<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppHeader from '../components/AppHeader.vue'
import { damageResult, healthPenalty, opposedResult } from '../rules/rulesEngine'
import { attributes } from '../data/bramble'
import { loreSpells } from '../data/magicOptions'
import { spellDetails } from '../data/magicDetails'
import { loadCharacters, type CharacterRecord, type PurchasedEquipment } from '../services/characters'
import { loadEncounters, writeEncounters, type EncounterRecord } from '../services/encounters'

type StrikeType='melee'|'ranged'|'magical'
const route=useRoute(),router=useRouter()
const encounters=ref<EncounterRecord[]>(loadEncounters())
const characters=ref<CharacterRecord[]>(loadCharacters().filter(character=>!character.draft))
const encounterId=computed(()=>String(route.params.id||''))
const encounter=computed(()=>encounters.value.find(item=>item.id===encounterId.value)||null)
const character=computed(()=>encounter.value?characters.value.find(item=>item.id===encounter.value?.characterId)||null:null)
function stamp(){return new Date().toISOString()}
function persist(){writeEncounters(encounters.value)}
function attribute(key:'agility'|'might'|'hide'|'lore'|'bravery'){return Number(character.value?.attributes?.[key]||0)}
function attributeMod(key:'agility'|'might'|'hide'|'lore'|'bravery'){return attribute(key)*2}
const gearGutsBonus=computed(()=>Math.max(0,...(character.value?.equipment||[]).map(item=>{const match=String(item.detail||'').match(/Guts Bonus\s*\+?(\d+)/i);return match?Number(match[1]):0})))
const secondaryStats=computed(()=>({speed:2+attribute('agility'),aim:attribute('agility')*2,mettle:attribute('might')*2,ward:attribute('hide')*2,control:attribute('lore')*2,power:attribute('might'),guts:attribute('hide')+gearGutsBonus.value}))
const magicLevel=computed(()=>character.value?.path==='magic'?1:0)
const manaRegen=computed(()=>2+magicLevel.value)
const skillEntries=computed(()=>Object.entries(character.value?.skillRanks||{}).sort(([a],[b])=>a.localeCompare(b)))
const characterSpells=computed(()=>{const c=character.value;if(!c)return[];const signature=c.loreAttunement?loreSpells[c.loreAttunement]?.[0]:'';return Array.from(new Set([signature,...(c.spells||[]),...(c.invocationSpells||[]),c.invocationSpell||''].filter(Boolean) as string[]))})
const weapons=computed(()=>(character.value?.equipment||[]).filter(item=>item.category==='Weapon'))
function skillModifier(rank:number){return Number(rank||0)*2}
function addEvent(text:string){const item=encounter.value;if(!item)return;item.events=[`${new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})} — ${text}`,...item.events].slice(0,40);item.lastResult=text;item.updatedAt=stamp();persist()}
const encounterHealth=computed({get:()=>encounter.value?.health??30,set:(value:number)=>{const item=encounter.value;if(!item)return;const before=item.health;item.health=Math.max(0,Number(value||0));if(before<=0&&item.health>0)item.fateMarks=0;item.updatedAt=stamp();persist()}})
const encounterFateMarks=computed({get:()=>encounter.value?.fateMarks??0,set:(value:number)=>{const item=encounter.value;if(!item)return;item.fateMarks=Math.max(0,Math.min(3,Number(value||0)));item.updatedAt=stamp();persist()}})
const encounterMana=computed({get:()=>encounter.value?.mana??0,set:(value:number)=>{const item=encounter.value;if(!item)return;item.mana=Math.max(0,Number(value||0));item.updatedAt=stamp();persist()}})
function changeRound(delta:number){const item=encounter.value;if(!item)return;const before=item.round;item.round=Math.max(1,item.round+delta);if(item.round>before){item.mana+=manaRegen.value;addEvent(`Round ${item.round}: +${manaRegen.value} Mana restored at the start of the round.`)}else{item.updatedAt=stamp();persist()}resetRoundAbilities()}
function completeEncounter(){const item=encounter.value;if(!item)return;item.status='completed';item.updatedAt=stamp();persist()}
function reopenEncounter(){const item=encounter.value;if(!item)return;item.status='ongoing';item.updatedAt=stamp();persist()}
function deleteEncounter(){const item=encounter.value;if(!item||!confirm('Delete this encounter and its local history?'))return;encounters.value=encounters.value.filter(entry=>entry.id!==item.id);persist();void router.push('/simulator')}

const abilitySpent=reactive({instinct:false,movement:false,combat:false,reaction:false})
const abilityTypes=['instinct','movement','combat','reaction'] as const
const abilityRemaining=computed(()=>abilityTypes.filter(type=>!abilitySpent[type]))
function resetRoundAbilities(){abilityTypes.forEach(type=>abilitySpent[type]=false)}
function toggleAbility(type:(typeof abilityTypes)[number]){abilitySpent[type]=!abilitySpent[type]}
const abilityStatus=computed(()=>abilityRemaining.value.length===0?'No Root ability types remain this round. Passive Abilities may still apply when their trigger and restrictions are met.':abilityRemaining.value.length===4?'Round ready: all four Root ability types are available.':`${abilityRemaining.value.length} Root ability type${abilityRemaining.value.length===1?'':'s'} remaining this round.`)

function die(){const a=new Uint32Array(1);crypto.getRandomValues(a);return(a[0]%10)+1}
function dice(count:number){return Array.from({length:count},die)}
const sheetResult=ref<{label:string;dice:number[];bonus:number;conditions:number;total:number}|null>(null)
function rollSheetStat(label:string,bonus:number,conditions=0){const rolled=dice(3);const total=rolled.reduce((sum,value)=>sum+value,0)+bonus+conditions;sheetResult.value={label,dice:rolled,bonus,conditions,total};addEvent(`${label}: ${rolled.join(' + ')} + ${bonus}${conditions?` ${conditions>=0?'+':'−'} ${Math.abs(conditions)} Conditions`:''} = ${total}.`)}

const strikeTypes:StrikeType[]=['melee','ranged','magical']
const strikeType=ref<StrikeType>('melee'),strikeCond=ref(0),targetWard=ref(0),targetWardCond=ref(0)
const strikeStatValue=computed(()=>strikeType.value==='melee'?secondaryStats.value.mettle:strikeType.value==='ranged'?secondaryStats.value.aim:secondaryStats.value.control)
const strikeStatLabel=computed(()=>strikeType.value==='melee'?'Mettle':strikeType.value==='ranged'?'Aim':'Control')
const combatResult=ref<ReturnType<typeof opposedResult>|null>(null)
const activeWeapon=ref('')
function rollCombat(label='Attack'){combatResult.value=opposedResult(dice(3),strikeStatValue.value,strikeCond.value,dice(3),Number(targetWard.value||0),targetWardCond.value);abilitySpent.combat=true;addEvent(`${label}: ${strikeType.value[0].toUpperCase()+strikeType.value.slice(1)} ${combatResult.value.hit?'Hit':'Miss'} — Strike ${combatResult.value.strike.total}, Target Ward ${combatResult.value.ward.total}`)}
function weaponStrikeType(item:PurchasedEquipment):StrikeType{return /projectile|thrown|bow|crossbow|sling|dart|blowpipe/i.test(`${item.name} ${item.detail||''}`)?'ranged':'melee'}
function weaponDamage(item:PurchasedEquipment){const text=String(item.detail||'');const labeled=text.match(/Damage\s+(\d+)/i);if(labeled)return Number(labeled[1]);const profile=text.match(/^\s*(\d+)\s*(?:·|$)/);return profile?Number(profile[1]):0}
function attackWithWeapon(item:PurchasedEquipment){strikeType.value=weaponStrikeType(item);activeWeapon.value=item.name;rollCombat(item.name)}
function weaponDamageDisplay(item:PurchasedEquipment){const base=weaponDamage(item);const bonus=weaponStrikeType(item)==='ranged'?attribute('agility'):secondaryStats.value.power;return base?`${base} + ${bonus} ${weaponStrikeType(item)==='ranged'?'Accuracy':'Power'}`:'See weapon profile'}

const damage=ref(8),damageType=ref<'standard'|'direct'|'lethal'>('standard'),equipmentExtra=ref(0),damageCond=ref(0),resistance=ref(0),weakness=ref(0)
const netDamageConditions=computed(()=>Number(damageCond.value||0)+Math.abs(Number(resistance.value||0))-Math.abs(Number(weakness.value||0)))
const damageCalc=computed(()=>damageResult(damage.value,damageType.value,attribute('hide'),gearGutsBonus.value+Number(equipmentExtra.value||0),netDamageConditions.value))
function applyDamage(){if(!encounter.value)return;encounterHealth.value=Math.max(0,encounterHealth.value-damageCalc.value.suffered);addEvent(`${damageCalc.value.suffered} ${damageType.value} damage suffered; Health ${encounterHealth.value}.`)}
const hallows=ref<number|null>(null)
function rollHallows(){hallows.value=die();if(hallows.value>=6)addEvent(`Hallows ${hallows.value}: pass.`);else{encounterFateMarks.value=Math.min(3,encounterFateMarks.value+1);addEvent(`Hallows ${hallows.value}: fail; Fate Mark ${encounterFateMarks.value}/3.`)}}
const healthPenaltyValue=computed(()=>healthPenalty(encounterHealth.value))

const spellName=ref(''),spellBaseCostManual=ref(0),spellAdjustment=ref(0)
const selectedSpellDetail=computed(()=>spellName.value?spellDetails[spellName.value]:undefined)
const selectedSpellBaseCost=computed(()=>selectedSpellDetail.value?.manaCost===null||selectedSpellDetail.value?.manaCost===undefined?Number(spellBaseCostManual.value||0):Number(selectedSpellDetail.value.manaCost))
const selectedSpellAttuned=computed(()=>Boolean(character.value?.loreAttunement&&selectedSpellDetail.value?.lore===character.value.loreAttunement))
const spellEffectiveCost=computed(()=>Math.max(0,selectedSpellBaseCost.value-(selectedSpellAttuned.value?2:0)+Number(spellAdjustment.value||0)))
function recordSpell(){if(!encounter.value||!spellName.value.trim())return;if(spellEffectiveCost.value>encounterMana.value){alert('The encounter does not have enough Mana for this cost.');return}encounterMana.value-=spellEffectiveCost.value;addEvent(`Cast ${spellName.value.trim()} for ${spellEffectiveCost.value} Mana; ${encounterMana.value} Mana remaining.`)}
</script>

<template>
  <main class="page encounter-page">
    <AppHeader compact back-to="/simulator" back-label="Back to Rhythm Engine" prefer-back-to />
    <template v-if="encounter && character">
      <nav class="rule-breadcrumb encounter-back-link"><RouterLink to="/simulator">Rhythm Engine</RouterLink><span>›</span><strong>Combat Encounter</strong></nav>
      <div class="page-title-block encounter-page-heading"><div><h1>{{ encounter.name }}</h1><p>{{ character.name }} · {{ character.species }}<template v-if="character.campaignName"> · {{ character.campaignName }}</template></p></div><div class="round-control"><button type="button" class="icon-button" @click="changeRound(-1)">−</button><span><small>ROUND</small><strong>{{ encounter.round }}</strong></span><button type="button" class="icon-button" @click="changeRound(1)">+</button></div></div>

      <section class="encounter-character-sheet card-surface">
        <header class="sheet-identity"><div><small>CHARACTER</small><h2>{{ character.name }}</h2><p>{{ character.species }} · {{ character.homeland }} · {{ character.path==='magic'?'Wind-Touched':'Gifted Heart' }}</p></div><div class="sheet-vitals"><label><span>Health</span><input v-model.number="encounterHealth" type="number" min="0" max="30" /></label><label><span>Mana</span><input v-model.number="encounterMana" type="number" min="0" /></label><label><span>Fate</span><input v-model.number="encounterFateMarks" type="number" min="0" max="3" /></label></div></header>

        <div class="sheet-section"><h3>Attributes</h3><div class="sheet-stat-grid attributes"><button v-for="item in attributes" :key="item.id" type="button" @click="rollSheetStat(`${item.name} Check`,attributeMod(item.id))"><span>{{ item.name }}</span><strong>{{ character.attributes[item.id] }}</strong><small>Mod +{{ attributeMod(item.id) }}</small></button></div></div>
        <div class="sheet-section"><h3>Secondary Stats</h3><div class="sheet-stat-grid secondary"><button type="button" @click="rollSheetStat('Initiative',secondaryStats.speed)"><span>Speed</span><strong>{{ secondaryStats.speed }}</strong><small>Roll Initiative</small></button><button type="button" @click="strikeType='ranged';rollCombat('Aim Strike')"><span>Aim</span><strong>{{ secondaryStats.aim }}</strong><small>Roll Ranged Strike</small></button><button type="button" @click="strikeType='melee';rollCombat('Mettle Strike')"><span>Mettle</span><strong>{{ secondaryStats.mettle }}</strong><small>Roll Melee Strike</small></button><button type="button" @click="rollSheetStat('Ward',secondaryStats.ward)"><span>Ward</span><strong>{{ secondaryStats.ward }}</strong><small>Roll Ward</small></button><button type="button" @click="strikeType='magical';rollCombat('Control Strike')"><span>Control</span><strong>{{ secondaryStats.control }}</strong><small>Roll Magical Strike</small></button><div><span>Power</span><strong>{{ secondaryStats.power }}</strong><small>Damage bonus</small></div><div><span>Guts</span><strong>{{ secondaryStats.guts }}</strong><small><template v-if="gearGutsBonus">Includes +{{ gearGutsBonus }} gear</template><template v-else>Damage soak</template></small></div></div></div>

        <div class="sheet-section attack-target-section"><h3>Attack Target</h3><div class="field-grid three"><label class="field-label">Target Ward<input v-model.number="targetWard" class="field-control" type="number" min="0" /></label><label class="field-label">Target Ward Conditions<input v-model.number="targetWardCond" class="field-control" type="number" /></label><label class="field-label">Your Strike Conditions<input v-model.number="strikeCond" class="field-control" type="number" /></label></div></div>

        <div class="sheet-section"><h3>Weapons</h3><div v-if="weapons.length" class="sheet-weapon-grid"><button v-for="weapon in weapons" :key="weapon.name" type="button" class="sheet-weapon-card" :class="{active:activeWeapon===weapon.name}" @click="attackWithWeapon(weapon)"><span>{{ weaponStrikeType(weapon)==='ranged'?'RANGED':'MELEE' }}</span><strong>{{ weapon.name }}</strong><small>{{ weaponDamageDisplay(weapon) }}</small><em>{{ weapon.detail }}</em></button></div><p v-else class="muted">No purchased weapons are recorded on this character.</p></div>

        <div v-if="sheetResult" class="sheet-roll-result"><span>{{ sheetResult.label }}</span><strong>{{ sheetResult.total }}</strong><small>{{ sheetResult.dice.join(' + ') }} + {{ sheetResult.bonus }}<template v-if="sheetResult.conditions"> {{ sheetResult.conditions>=0?'+':'−' }} {{ Math.abs(sheetResult.conditions) }}</template></small></div>
        <div v-if="combatResult" class="sheet-roll-result attack-result" :class="combatResult.hit?'good':'bad'"><span>{{ activeWeapon||`${strikeStatLabel} Strike` }}</span><strong>{{ combatResult.hit?'HIT':'MISS' }}</strong><small>Strike {{ combatResult.strike.total }} · Ward {{ combatResult.ward.total }}</small></div>

        <details class="sheet-detail"><summary>Skills</summary><div class="sheet-detail-body"><p v-for="([skill,rank]) in skillEntries" :key="skill"><strong>{{ skill }}</strong> · Rank {{ rank }} · Mod +{{ skillModifier(rank) }}</p><p v-if="!skillEntries.length" class="muted">No skills recorded.</p></div></details>
        <details v-if="character.talents?.length" class="sheet-detail"><summary>Talents</summary><div class="sheet-detail-body"><p v-for="talent in character.talents" :key="talent">{{ talent }}</p></div></details>
        <details v-if="character.path==='magic'" class="sheet-detail"><summary>Magic &amp; Spells</summary><div class="sheet-detail-body"><p><strong>{{ character.loreAttunement||'No Lore' }}</strong> · {{ manaRegen }} Mana restored/round</p><button v-for="spell in characterSpells" :key="spell" type="button" class="sheet-spell-button" @click="spellName=spell">{{ spell }}</button></div></details>
      </section>

      <div class="active-encounter-tools">
        <details class="encounter-tool-panel abilities-panel" open><summary>Abilities</summary><div class="encounter-tool-body"><p class="ability-help">Resolve start-of-turn triggers first. Root limits allow one Instinct, Movement, Combat, and Reaction Root use per type each round.</p><div class="ability-root-grid"><button v-for="type in abilityTypes" :key="type" type="button" :class="{spent:abilitySpent[type]}" @click="toggleAbility(type)"><span>Root {{ type }}</span><strong>{{ abilitySpent[type]?'Used':'Available' }}</strong></button><article class="passive-ability-card"><span>Passive</span><strong>Trigger Based</strong><small>Does not consume a Root type.</small></article></div><div class="ability-status" :class="{empty:abilityRemaining.length===0}">{{ abilityStatus }}</div><button class="secondary-button wide" @click="resetRoundAbilities">Reset Round Abilities</button></div></details>

        <details class="encounter-tool-panel"><summary>Attacking &amp; Defending</summary><div class="encounter-tool-body"><div class="strike-type-tabs"><button v-for="type in strikeTypes" :key="type" :class="{active:strikeType===type}" @click="strikeType=type">{{ type[0].toUpperCase()+type.slice(1) }} Strike</button></div><div class="field-grid two"><label><span>{{ strikeStatLabel }} Strike</span><div class="field-control stat-readout">{{ strikeStatValue }}</div></label><label><span>Strike Conditions</span><input v-model.number="strikeCond" class="field-control" type="number" /></label><label><span>Target Ward</span><input v-model.number="targetWard" class="field-control" type="number" min="0" /></label><label><span>Target Ward Conditions</span><input v-model.number="targetWardCond" class="field-control" type="number" /></label></div><button class="primary-button wide" @click="rollCombat()">Roll {{ strikeType[0].toUpperCase()+strikeType.slice(1) }} Strike</button></div></details>

        <details class="encounter-tool-panel"><summary>Spells &amp; Mana</summary><div class="encounter-tool-body"><div class="field-grid two"><label><span>Spell</span><select v-model="spellName" class="field-control"><option value="">Choose a Spell</option><option v-for="spell in characterSpells" :key="spell" :value="spell">{{ spell }}</option></select></label><label><span>Base Mana Cost</span><input v-model.number="spellBaseCostManual" class="field-control" type="number" min="0" :disabled="selectedSpellDetail?.manaCost!==null&&selectedSpellDetail?.manaCost!==undefined" /></label><label><span>Attunement</span><div class="field-control stat-readout">{{ selectedSpellAttuned?'−2 Mana':'No reduction' }}</div></label><label><span>Other Mana Adjustment</span><input v-model.number="spellAdjustment" class="field-control" type="number" /></label></div><article v-if="selectedSpellDetail" class="spell-encounter-card"><div><span>{{ selectedSpellDetail.lore }}</span><strong>{{ spellName }}</strong><b v-if="selectedSpellDetail.manaCost!==null">{{ spellEffectiveCost }} Mana</b></div><p>{{ selectedSpellDetail.flavor }}</p></article><div class="sim-stat-total"><span>Recorded Mana Cost</span><strong>{{ spellEffectiveCost }}</strong><small>{{ encounterMana }} available · {{ manaRegen }} restored/round</small></div><button class="secondary-button wide" :disabled="!spellName||spellEffectiveCost>encounterMana" @click="recordSpell">Record Spell Use</button></div></details>

        <details class="encounter-tool-panel"><summary>Damage &amp; Guts</summary><div class="encounter-tool-body"><div class="field-grid three"><label><span>Incoming Damage</span><input v-model.number="damage" class="field-control" type="number" min="0" /></label><label><span>Damage Type</span><select v-model="damageType" class="field-control"><option value="standard">Standard</option><option value="direct">Direct</option><option value="lethal">Lethal</option></select></label><label><span>Base Guts</span><div class="field-control stat-readout">{{ attribute('hide') }}</div></label><label><span>Gear Guts</span><div class="field-control stat-readout">{{ gearGutsBonus }}</div></label><label><span>Other Equipment Guts</span><input v-model.number="equipmentExtra" class="field-control" type="number" min="0" /></label><label><span>Conditions</span><input v-model.number="damageCond" class="field-control" type="number" /></label><label><span>Resistance</span><input v-model.number="resistance" class="field-control" type="number" min="0" /></label><label><span>Weakness</span><input v-model.number="weakness" class="field-control" type="number" min="0" /></label></div><div class="metric-grid"><div><span>Effective Guts</span><strong>{{ damageCalc.guts }}</strong></div><div><span>Damage Suffered</span><strong>{{ damageCalc.suffered }}</strong></div></div><button class="secondary-button wide" @click="applyDamage">Apply Damage</button></div></details>

        <details class="encounter-tool-panel"><summary>Health, Hallows &amp; Fate Marks</summary><div class="encounter-tool-body"><div class="metric-grid"><div><span>Health Penalty</span><strong>{{ healthPenaltyValue===null?'Defeated':healthPenaltyValue }}</strong></div><div><span>Fate Marks</span><strong>{{ encounterFateMarks }} / 3</strong></div></div><button class="secondary-button wide" @click="rollHallows">Roll 1d10 Hallows Save</button><div v-if="hallows!==null" class="notice" :class="hallows>=6?'good':'bad'">{{ hallows>=6?`PASS — ${hallows}`:`FAIL — ${hallows}; Fate Mark ${encounterFateMarks}/3.` }}</div></div></details>
        <details v-if="encounter.events.length" class="encounter-tool-panel"><summary>Encounter Log</summary><div class="encounter-log"><p v-for="(event,index) in encounter.events" :key="index">{{ event }}</p></div></details>
      </div>
      <div class="encounter-page-actions"><button v-if="encounter.status==='ongoing'" class="secondary-button" @click="completeEncounter">Complete Encounter</button><button v-else class="secondary-button" @click="reopenEncounter">Reopen Encounter</button><button class="danger-button" @click="deleteEncounter">Delete Encounter</button></div>
    </template>
    <section v-else class="empty-state card-surface"><h2>Encounter Not Found</h2><p>The encounter or its saved character is not available on this device.</p><RouterLink class="primary-button" to="/simulator">Back to Rhythm Engine</RouterLink></section>
  </main>
</template>

<style scoped>
.rule-breadcrumb{display:flex;gap:7px;align-items:center;color:var(--ink-soft)}.rule-breadcrumb a{color:var(--accent-dark);font-weight:800;text-decoration:none}.round-control{display:grid;grid-template-columns:36px 60px 36px;align-items:center;gap:4px}.round-control>span{text-align:center}.round-control small{display:block;font-size:8px}.round-control strong{font-size:20px}.encounter-character-sheet{overflow:hidden;margin-bottom:12px;border-top:7px solid var(--accent)}.sheet-identity{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 15px;border-bottom:1px solid var(--line);background:var(--paper-2)}.sheet-identity h2{margin:2px 0;font-family:Georgia,'Times New Roman',serif}.sheet-identity p{margin:0;color:var(--ink-soft)}.sheet-vitals{display:grid;grid-template-columns:repeat(3,76px);gap:6px}.sheet-vitals label{display:grid;gap:3px;color:var(--ink-soft);font-size:9px;font-weight:850;text-align:center}.sheet-vitals input{width:100%;min-height:38px;border:1px solid var(--line-dark);border-radius:7px;background:var(--paper);color:var(--ink);font-weight:900;text-align:center}.sheet-section{padding:11px 14px;border-bottom:1px solid var(--line)}.sheet-section>h3{margin:0 0 8px;font-family:Georgia,'Times New Roman',serif;font-size:15px}.sheet-stat-grid{display:grid;gap:6px}.sheet-stat-grid.attributes{grid-template-columns:repeat(5,minmax(0,1fr))}.sheet-stat-grid.secondary{grid-template-columns:repeat(7,minmax(0,1fr))}.sheet-stat-grid button,.sheet-stat-grid>div{min-width:0;display:grid;justify-items:center;gap:2px;padding:8px 5px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink)}.sheet-stat-grid button{cursor:pointer}.sheet-stat-grid button:hover{border-color:var(--accent);background:var(--accent-wash)}.sheet-stat-grid span{font-size:8px;color:var(--ink-soft);font-weight:850}.sheet-stat-grid strong{font-size:18px}.sheet-stat-grid small{font-size:8px;color:var(--ink-soft);text-align:center}.sheet-weapon